    dst_p[2] |= pack_left_shift_u8(src_p->hv_on_inhibit_cold, 4u, 0x10u);
    dst_p[2] |= pack_left_shift_u8(src_p->balance_active, 5u, 0x20u);
    dst_p[2] |= pack_left_shift_u8(src_p->safe_reset_allowed, 6u, 0x40u);
    dst_p[2] |= pack_left_shift_u8(src_p->charge_mode_active, 7u, 0x80u);
