    dst_p[3] |= pack_left_shift_u8(src_p->air_p_intended, 6u, 0x40u);
    dst_p[3] |= pack_left_shift_u8(src_p->air_p_actual, 7u, 0x80u);
    dst_p[4] |= pack_left_shift_u8(src_p->dcdc_switch, 0u, 0x01u);
