    dst_p[4] |= pack_left_shift_u8(src_p->por_state_n, 4u, 0x10u);
    dst_p[4] |= pack_left_shift_u8(src_p->sc_latched, 5u, 0x20u);
    dst_p[4] |= pack_left_shift_u8(src_p->danger_voltage, 6u, 0x40u);
    dst_p[4] |= pack_left_shift_u8(src_p->tsal_green_actual, 7u, 0x80u);
    dst_p[5] |= pack_left_shift_u8(src_p->primary_fault_id, 0u, 0xffu);
    dst_p[6] |= pack_left_shift_u8(src_p->fault_severity, 0u, 0x07u);
