    dst_p[7] |= pack_left_shift_u8(src_p->soc_quality, 6u, 0xc0u);
    dst_p[8] |= pack_left_shift_u32(src_p->runtime_seconds, 0u, 0xffu);
    dst_p[9] |= pack_right_shift_u32(src_p->runtime_seconds, 8u, 0xffu);
    dst_p[10] |= pack_right_shift_u32(src_p->runtime_seconds, 16u, 0xffu);
    dst_p[11] |= pack_right_shift_u32(src_p->runtime_seconds, 24u, 0xffu);
