    dst_p[23] |= pack_right_shift_u16(cell_temperature_min, 8u, 0xffu);
    cell_temperature_max = (uint16_t)src_p->cell_temperature_max;
    dst_p[24] |= pack_left_shift_u16(cell_temperature_max, 0u, 0xffu);
    dst_p[25] |= pack_right_shift_u16(cell_temperature_max, 8u, 0xffu);
    dst_p[26] |= pack_left_shift_u8(src_p->cell_temperature_min_index, 0u, 0xffu);
    dst_p[27] |= pack_left_shift_u8(src_p->cell_temperature_max_index, 0u, 0xffu);
    dst_p[28] |= pack_left_shift_u8(src_p->ntc_valid_count, 0u, 0xffu);
    dst_p[29] |= pack_left_shift_u8(src_p->ntc_invalid_count, 0u, 0xffu);
    dst_p[30] |= pack_left_shift_u16(src_p->soc, 0u, 0xffu);
    dst_p[31] |= pack_right_shift_u16(src_p->soc, 8u, 0xffu);
    dst_p[32] |= pack_left_shift_u16(src_p->soh, 0u, 0xffu);
    dst_p[33] |= pack_right_shift_u16(src_p->soh, 8u, 0xffu);
    dst_p[34] |= pack_left_shift_u16(src_p->p_discharge_max, 0u, 0xffu);
    dst_p[35] |= pack_right_shift_u16(src_p->p_discharge_max, 8u, 0xffu);
    dst_p[36] |= pack_left_shift_u16(src_p->p_charge_max, 0u, 0xffu);
    dst_p[37] |= pack_right_shift_u16(src_p->p_charge_max, 8u, 0xffu);
    pack_current_measured = (uint32_t)src_p->pack_current_measured;
    dst_p[38] |= pack_left_shift_u32(pack_current_measured, 0u, 0xffu);
    dst_p[39] |= pack_right_shift_u32(pack_current_measured, 8u, 0xffu);
    dst_p[40] |= pack_right_shift_u32(pack_current_measured, 16u, 0xffu);
    dst_p[41] |= pack_right_shift_u32(pack_current_measured, 24u, 0xffu);
    pack_power_measured = (uint32_t)src_p->pack_power_measured;
    dst_p[42] |= pack_left_shift_u32(pack_power_measured, 0u, 0xffu);
    dst_p[43] |= pack_right_shift_u32(pack_power_measured, 8u, 0xffu);
    dst_p[44] |= pack_right_shift_u32(pack_power_measured, 16u, 0xffu);
    dst_p[45] |= pack_right_shift_u32(pack_power_measured, 24u, 0xffu);
    dst_p[46] |= pack_left_shift_u32(src_p->imd_resistance, 0u, 0xffu);
    dst_p[47] |= pack_right_shift_u32(src_p->imd_resistance, 8u, 0xffu);
    dst_p[48] |= pack_right_shift_u32(src_p->imd_resistance, 16u, 0xffu);
    dst_p[49] |= pack_right_shift_u32(src_p->imd_resistance, 24u, 0xffu);
    dst_p[50] |= pack_left_shift_u16(src_p->imd_frequency, 0u, 0xffu);
    dst_p[51] |= pack_right_shift_u16(src_p->imd_frequency, 8u, 0xffu);
    dst_p[52] |= pack_left_shift_u16(src_p->imd_duty_cycle, 0u, 0xffu);
    dst_p[53] |= pack_right_shift_u16(src_p->imd_duty_cycle, 8u, 0xffu);
    dst_p[54] |= pack_left_shift_u32(src_p->leakage_resistance1, 0u, 0xffu);
    dst_p[55] |= pack_right_shift_u32(src_p->leakage_resistance1, 8u, 0xffu);
    dst_p[56] |= pack_right_shift_u32(src_p->leakage_resistance1, 16u, 0xffu);
    dst_p[57] |= pack_right_shift_u32(src_p->leakage_resistance1, 24u, 0xffu);
    dst_p[58] |= pack_left_shift_u32(src_p->leakage_resistance2, 0u, 0xffu);
    dst_p[59] |= pack_right_shift_u32(src_p->leakage_resistance2, 8u, 0xffu);
    dst_p[60] |= pack_right_shift_u32(src_p->leakage_resistance2, 16u, 0xffu);
    dst_p[61] |= pack_right_shift_u32(src_p->leakage_resistance2, 24u, 0xffu);
    dst_p[62] |= pack_left_shift_u8(src_p->status_age, 0u, 0x3fu);
    dst_p[62] |= pack_left_shift_u8(src_p->developer_mode, 6u, 0xc0u);
    dst_p[63] |= pack_left_shift_u8(src_p->status_crc8, 0u, 0xffu);

